from dataclasses import asdict
from method.schema import StageContext, TestScenario, ScenarioStep, GroundingMap, GroundedElement
from method.stages.api import run_sd2_parse, run_sd3_semantic, run_sd4_design, run_sd5a_scenario_coverage, freeze_scenario_set, run_sd6_sim
import hashlib, json

dsl = '''def int CA_mode = 0;
def int control_owned = 0;
def int flow_source = 0;
def int flow_command = 0;
def int current_bp_level = 1;
def int target_bp = 80;
def int setpoint_change_count = 0;
def int pump_fault = 0;
def int pump_alarm = 0;
def int error_message = 0;
def int log_count = 0;

state CARA_Mode_Control {
    event RequestAC;
    event ChangeSetpoint;
    event StartAC;
    event BP_Low;
    event BP_Normal;
    event BP_High;
    event PumpFault;
    event FaultRemoved;
    event TerminateAC;
    event CA_backManual;
    event CB_backManual;
    event CP_backManual;
    event CC_backManual;

    "'! * -> PumpFault : /PumpFault;
    ! * -> Manual : /CA_backManual;
    ! * -> Manual : /CB_backManual;
    ! * -> Manual : /CP_backManual;
    ! * -> Manual : /CC_backManual;

    [*] -> Wait;

    state Wait;

    state Manual {
        enter {
            CA_mode = 0;
            control_owned = 0;
            flow_source = 0;
            flow_command = 0;
        }
    }

    state Ask_StartAC {
        enter {
            CA_mode = 1;
            flow_source = 0;
        }
        [*] -> Prompting;
        state Prompting;
        Prompting -> Prompting : /ChangeSetpoint effect {
            target_bp = target_bp + 5;
            setpoint_change_count = setpoint_change_count + 1;
        };
    }

    state AutocontrolInit {
        enter {
            CA_mode = 2;
            control_owned = 1;
            flow_source = 1;
            pump_alarm = 0;
            error_message = 0;
        }
    }

    state Autocontrol {
        enter {
            CA_mode = 3;
            control_owned = 1;
            flow_source = 1;
        }
        during {
            log_count = log_count + 1;
            if [current_bp_level >= 2] {
                flow_command = 1;
            } else if [current_bp_level == 1] {
                flow_command = 2;
            } else {
                flow_command = 3;
            }
        }
    }

    state PumpFault {
        enter {
            pump_fault = 1;
            pump_alarm = 1;
            error_message = 1;
            control_owned = 0;
            flow_source = 0;
            CA_mode = 0;
        }
    }

    Wait -> Manual;
    Manual -> Ask_StartAC : /RequestAC;
    Ask_StartAC -> AutocontrolInit : /StartAC;
    AutocontrolInit -> Autocontrol;
    Ask_StartAC -> Manual : /TerminateAC;
    AutocontrolInit -> Manual : /TerminateAC;
    Autocontrol -> Manual : /TerminateAC;
    Autocontrol -> Autocontrol : /BP_Low effect {
        current_bp_level = 0;
        flow_command = 3;
    };
    Autocontrol -> Autocontrol : /BP_Normal effect {
        current_bp_level = 1;
        flow_command = 2;
    };
    Autocontrol -> Autocontrol : /BP_High effect {
        current_bp_level = 2;
        flow_command = 1;
    };
    PumpFault -> Manual : /FaultRemoved effect {
        pump_fault = 0;
        pump_alarm = 0;
        error_message = 0;
    };
}
'"'''
context=StageContext(nl='CARA pump modes and fallback; sensor readings external; higher BP lower flow; StartAC enters AutocontrolInit; pump fault alarm and release; backManual to Manual', current_dsl=dsl)
run_sd2_parse(dsl, context); run_sd3_semantic(dsl, context); run_sd4_design(context, policy_profile='generated_candidate')
scenarios=[
    TestScenario(name='default_initializes_manual', description='default prefix reaches Manual after startup fall-through', steps=[ScenarioStep(events=[], expected_state='CARA_Mode_Control.Manual', expected_vars={'CA_mode':0,'control_owned':0,'flow_source':0}, name='startup_to_manual')]),
    TestScenario(name='ask_startac_setpoint_then_autocontrol', description='manual RequestAC enters Ask_StartAC; setpoint can change; StartAC enters AutocontrolInit then Autocontrol', steps=[
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Manual', name='startup'),
        ScenarioStep(events=['/RequestAC'], expected_state='CARA_Mode_Control.Ask_StartAC.Prompting', expected_vars={'CA_mode':1}, name='request_ac'),
        ScenarioStep(events=['/ChangeSetpoint'], expected_state='CARA_Mode_Control.Ask_StartAC.Prompting', expected_vars={'target_bp':85,'setpoint_change_count':1}, name='change_setpoint'),
        ScenarioStep(events=['/StartAC'], expected_state='CARA_Mode_Control.AutocontrolInit', expected_vars={'CA_mode':2,'control_owned':1,'flow_source':1}, name='start_ac'),
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Autocontrol', expected_vars={'CA_mode':3,'control_owned':1,'flow_source':1,'flow_command':2,'log_count':1}, name='autocontrol_entry')
    ]),
    TestScenario(name='bp_high_reduces_flow_low_increases_flow', description='external BP events update discrete BP level; high pressure lower flow than low pressure', steps=[
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Manual', name='startup'),
        ScenarioStep(events=['/RequestAC'], expected_state='CARA_Mode_Control.Ask_StartAC.Prompting', name='request_ac'),
        ScenarioStep(events=['/StartAC'], expected_state='CARA_Mode_Control.AutocontrolInit', name='start_ac'),
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Autocontrol', expected_vars={'flow_command':2}, name='normal_flow'),
        ScenarioStep(events=['/BP_High'], expected_state='CARA_Mode_Control.Autocontrol', expected_vars={'current_bp_level':2,'flow_command':1}, name='bp_high_low_flow'),
        ScenarioStep(events=['/BP_Low'], expected_state='CARA_Mode_Control.Autocontrol', expected_vars={'current_bp_level':0,'flow_command':3}, name='bp_low_high_flow')
    ]),
    TestScenario(name='pump_fault_releases_control_and_alarm_then_manual', description='pump fault from autocontrol activates alarm, releases software control, caregiver clears fault to Manual', steps=[
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Manual', name='startup'),
        ScenarioStep(events=['/RequestAC'], expected_state='CARA_Mode_Control.Ask_StartAC.Prompting', name='request_ac'),
        ScenarioStep(events=['/StartAC'], expected_state='CARA_Mode_Control.AutocontrolInit', name='start_ac'),
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Autocontrol', name='autocontrol'),
        ScenarioStep(events=['/PumpFault'], expected_state='CARA_Mode_Control.PumpFault', expected_vars={'pump_fault':1,'pump_alarm':1,'error_message':1,'control_owned':0,'flow_source':0,'CA_mode':0}, name='fault_alarm_release'),
        ScenarioStep(events=['/FaultRemoved'], expected_state='CARA_Mode_Control.Manual', expected_vars={'pump_fault':0,'pump_alarm':0,'error_message':0,'CA_mode':0,'control_owned':0}, name='fault_removed_manual')
    ]),
    TestScenario(name='cross_component_backmanual_from_autocontrol', description='CB/CP/CC/CA backManual events all recover to Manual', steps=[
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Manual', name='startup'),
        ScenarioStep(events=['/RequestAC'], expected_state='CARA_Mode_Control.Ask_StartAC.Prompting', name='request_ac'),
        ScenarioStep(events=['/StartAC'], expected_state='CARA_Mode_Control.AutocontrolInit', name='start_ac'),
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Autocontrol', name='autocontrol'),
        ScenarioStep(events=['/CB_backManual'], expected_state='CARA_Mode_Control.Manual', expected_vars={'CA_mode':0,'control_owned':0,'flow_source':0}, name='cb_back_manual'),
        ScenarioStep(events=['/RequestAC'], expected_state='CARA_Mode_Control.Ask_StartAC.Prompting', name='request_ac_again'),
        ScenarioStep(events=['/StartAC'], expected_state='CARA_Mode_Control.AutocontrolInit', name='start_ac_again'),
        ScenarioStep(events=[], expected_state='CARA_Mode_Control.Autocontrol', name='autocontrol_again'),
        ScenarioStep(events=['/CP_backManual','/CC_backManual','/CA_backManual'], expected_state='CARA_Mode_Control.Manual', expected_vars={'CA_mode':0,'control_owned':0,'flow_source':0}, name='any_back_manual')
    ])
]
coverage, cm=run_sd5a_scenario_coverage(dsl, scenarios)
scenario_set, fm=freeze_scenario_set(scenarios, source_dsl_hash='sha256:'+hashlib.sha256(dsl.encode()).hexdigest(), source_inspect_hash='sha256:'+hashlib.sha256(repr(context.inspect_json or {}).encode()).hexdigest(), source_grounding_hash='sha256:'+hashlib.sha256(b'grounding').hexdigest(), coverage_report=coverage)
sim, sm=run_sd6_sim(dsl, scenario_set, context)
print('coverage meta', asdict(cm))
print(json.dumps(coverage, indent=2, ensure_ascii=False))
print('freeze meta', asdict(fm))
print('sim ok', sim.ok, 'pass', sim.n_scenarios_passed,'/',sim.n_scenarios)
for r in sim.scenario_results:
    print('\\nSCENARIO', r.name, r.status, 'setup', r.setup_error)
    for sr in r.step_results:
        print(sr.step_index, sr.step_name, sr.status, sr.actual_state, sr.actual_vars, sr.var_mismatches, sr.runtime_error)
PY"

